// ============================================
// IMAGE ERROR HANDLING
// ============================================

// Image Fallback Handler
function setupImageFallback() {
    const images = document.querySelectorAll('img');
    
    images.forEach(img => {
        // Add error handler
        img.addEventListener('error', function() {
            handleError('Image Load Error', `Failed to load: ${this.src}`);
            
            // Try fallback image
            const fallbackSrc = this.dataset.fallback || 'assets/resources/img/gurukripaLogo.jpg';
            if (this.src !== fallbackSrc) {
                this.src = fallbackSrc;
                this.alt = 'Image unavailable';
            } else {
                // If fallback also fails, show placeholder
                this.outerHTML = `
                    <div class="image-placeholder" style="
                        width: 100%;
                        height: 100%;
                        background: #f5f5f5;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        color: #999;
                        font-size: 0.9rem;
                        border-radius: inherit;
                    ">Image not available</div>
                `;
            }
        });
        
        // Add loading handler
        img.addEventListener('load', function() {
            this.classList.add('loaded');
        });
    });
}

// ============================================
// FLOATING BUTTON SAFETY CHECK
// ============================================

// Floating Button Safety
function setupFloatingButtons() {
    const floatingButtons = document.querySelectorAll('.floating-btn');
    
    floatingButtons.forEach(button => {
        // Add error handling for click events
        button.addEventListener('click', function(e) {
            try {
                // Prevent multiple clicks
                if (this.classList.contains('loading')) return;
                
                this.classList.add('loading');
                const originalContent = this.innerHTML;
                
                // Add loading spinner
                this.innerHTML = '<i class="ion-load-c"></i>';
                
                // Simulate action
                setTimeout(() => {
                    this.classList.remove('loading');
                    this.innerHTML = originalContent;
                }, 1000);
                
            } catch (error) {
                handleError('Floating Button Error', error);
                showUserFriendlyError('Action failed. Please try again.');
                this.classList.remove('loading');
            }
        });
    });
}

// ============================================
// SEARCH FUNCTIONALITY WITH ERROR HANDLING
// ============================================

// Debounced Search
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

// Safe Search Implementation
function setupSearch() {
    const searchInput = document.querySelector('.search-input');
    const searchBtn = document.querySelector('.search-btn');
    
    if (!searchInput || !searchBtn) return;
    
    const debouncedSearch = debounce(function() {
        try {
            const searchTerm = searchInput.value.toLowerCase().trim();
            const productCards = document.querySelectorAll('.product-card-modern');
            
            if (!searchTerm) {
                productCards.forEach(card => card.style.display = 'block');
                return;
            }
            
            let foundResults = false;
            productCards.forEach(card => {
                const title = card.querySelector('.product-title')?.textContent.toLowerCase();
                const description = card.querySelector('.product-description')?.textContent.toLowerCase();
                
                if (title?.includes(searchTerm) || description?.includes(searchTerm)) {
                    card.style.display = 'block';
                    foundResults = true;
                } else {
                    card.style.display = 'none';
                }
            });
            
            // Show no results message
            const noResults = document.querySelector('.no-results-message');
            if (noResults) noResults.remove();
            
            if (!foundResults && searchTerm) {
                const container = document.querySelector('.products-grid-modern');
                if (container) {
                    const noResultsDiv = document.createElement('div');
                    noResultsDiv.className = 'no-results-message';
                    noResultsDiv.style.cssText = `
                        grid-column: 1 / -1;
                        text-align: center;
                        padding: 40px;
                        color: #666;
                    `;
                    noResultsDiv.innerHTML = `
                        <div style="font-size: 3rem; margin-bottom: 15px;">🔍</div>
                        <h3>No results found</h3>
                        <p>Try a different keyword or browse all products</p>
                        <button onclick="clearSearch()" style="
                            background: #8B0000;
                            color: white;
                            border: none;
                            padding: 10px 20px;
                            border-radius: 8px;
                            cursor: pointer;
                            margin-top: 15px;
                        ">Clear Search</button>
                    `;
                    container.appendChild(noResultsDiv);
                }
            }
        } catch (error) {
            handleError('Search Error', error);
            showUserFriendlyError('Search failed. Please try again.');
        }
    }, 300);
    
    searchInput.addEventListener('input', debouncedSearch);
    searchBtn.addEventListener('click', debouncedSearch);
}

function clearSearch() {
    const searchInput = document.querySelector('.search-input');
    if (searchInput) {
        searchInput.value = '';
        const productCards = document.querySelectorAll('.product-card-modern');
        productCards.forEach(card => card.style.display = 'block');
        const noResults = document.querySelector('.no-results-message');
        if (noResults) noResults.remove();
    }
}

